/* =========================================================
   CHATGPT — SNOW MOUNTAIN MINIMAL
   Clean • Minimal • Glass • Dark Sidebar
   ========================================================= */


/* ---------- BACKGROUND IMAGE ---------- */

html,
body {
    background: #111 !important;
}

/* Main application background */
body::before {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -10;
    pointer-events: none;

    background-image:
        url("https://images.unsplash.com/photo-1464822759023-fed622ff2c3b?auto=format&fit=crop&w=2400&q=85");

    background-size: cover;
    background-position: center;
    background-repeat: no-repeat;

    filter: blur(4px);
    transform: scale(1.04);
}


/* ---------- DARK VIGNETTE ---------- */

body::after {
    content: "";
    position: fixed;
    inset: 0;
    z-index: -9;
    pointer-events: none;

    background:
        radial-gradient(
            ellipse at center,
            rgba(0,0,0,0.05) 25%,
            rgba(0,0,0,0.30) 70%,
            rgba(0,0,0,0.72) 100%
        );

    box-shadow:
        inset 0 0 180px rgba(0,0,0,0.70);
}


/* ---------- REMOVE DEFAULT CHATGPT BACKGROUNDS ---------- */

main,
main > div,
[class*="bg-token-main"],
[class*="bg-token-surface"],
[class*="bg-token-sidebar"] {
    background: transparent !important;
}


/* ---------- SIDEBAR ---------- */

aside {
    background:
        linear-gradient(
            160deg,
            rgba(48,48,52,0.96) 0%,
            rgba(29,29,32,0.97) 45%,
            rgba(10,10,12,0.99) 100%
        ) !important;

    border-right: 1px solid rgba(255,255,255,0.08) !important;

    box-shadow:
        10px 0 35px rgba(0,0,0,0.25) !important;

    backdrop-filter: blur(20px) saturate(110%);
    -webkit-backdrop-filter: blur(20px) saturate(110%);
}


/* Sidebar text */

aside a,
aside button {
    color: rgba(255,255,255,0.78) !important;
}


/* Sidebar hover */

aside a:hover,
aside button:hover {
    background: rgba(255,255,255,0.075) !important;
    border-radius: 10px !important;
}


/* ---------- CHAT AREA ---------- */

main {
    position: relative;
}


/* ---------- CHAT MESSAGES ---------- */

[data-message-author-role="user"],
[data-message-author-role="assistant"] {
    background: transparent !important;
}


/* Assistant message readability */

[data-message-author-role="assistant"] {
    text-shadow: 0 1px 12px rgba(0,0,0,0.35);
}


/* User message bubble */

[data-message-author-role="user"] > div {
    background:
        rgba(35,35,38,0.72) !important;

    border:
        1px solid rgba(255,255,255,0.08) !important;

    border-radius: 18px !important;

    box-shadow:
        0 8px 30px rgba(0,0,0,0.18) !important;

    backdrop-filter: blur(18px);
    -webkit-backdrop-filter: blur(18px);
}


/* ---------- GLASS COMPOSER ---------- */

form {
    background:
        rgba(25,25,28,0.78) !important;

    border:
        1px solid rgba(255,255,255,0.10) !important;

    border-radius: 22px !important;

    box-shadow:
        0 15px 50px rgba(0,0,0,0.30) !important;

    backdrop-filter: blur(24px) saturate(120%);
    -webkit-backdrop-filter: blur(24px) saturate(120%);
}


/* Composer input */

textarea,
[contenteditable="true"] {
    background: transparent !important;
}


/* ---------- TOP BAR ---------- */

header {
    background:
        linear-gradient(
            to bottom,
            rgba(15,15,17,0.45),
            rgba(15,15,17,0)
        ) !important;

    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
}


/* ---------- BUTTONS ---------- */

button {
    transition:
        background 0.18s ease,
        transform 0.18s ease,
        opacity 0.18s ease;
}

button:hover {
    background-color:
        rgba(255,255,255,0.08) !important;
}


/* ---------- CODE BLOCKS ---------- */

pre {
    background:
        rgba(12,12,14,0.88) !important;

    border:
        1px solid rgba(255,255,255,0.08) !important;

    border-radius: 14px !important;

    box-shadow:
        0 12px 35px rgba(0,0,0,0.25) !important;

    backdrop-filter: blur(15px);
}


/* ---------- MARKDOWN TABLES ---------- */

table {
    background:
        rgba(20,20,22,0.55) !important;

    border-radius: 12px;
    overflow: hidden;
}

th {
    background:
        rgba(255,255,255,0.07) !important;
}

td,
th {
    border-color:
        rgba(255,255,255,0.08) !important;
}


/* ---------- LINKS ---------- */

a {
    transition: opacity 0.15s ease;
}

a:hover {
    opacity: 0.78;
}


/* ---------- SCROLLBAR ---------- */

::-webkit-scrollbar {
    width: 7px;
    height: 7px;
}

::-webkit-scrollbar-track {
    background: transparent;
}

::-webkit-scrollbar-thumb {
    background:
        rgba(255,255,255,0.16);

    border-radius: 20px;
}

::-webkit-scrollbar-thumb:hover {
    background:
        rgba(255,255,255,0.25);
}


/* ---------- SELECTION ---------- */

::selection {
    background: rgba(255,255,255,0.20);
    color: white;
}


/* ---------- FOCUS ---------- */

textarea:focus,
[contenteditable="true"]:focus {
    outline: none !important;
}


/* ---------- REDUCE VISUAL NOISE ---------- */

/* Hide excessive borders */

[class*="border-token"] {
    border-color:
        rgba(255,255,255,0.07) !important;
}


/* ---------- MOBILE ---------- */

@media (max-width: 768px) {

    body::before {
        background-position: center;
        filter: blur(6px);
    }

    aside {
        background:
            linear-gradient(
                160deg,
                rgba(35,35,38,0.98),
                rgba(8,8,10,0.99)
            ) !important;
    }

    form {
        border-radius: 18px !important;
    }
}
